 for j,s in enumerate(D['mix'],1):pos[s].append(j)
 first=[pos[s][0] if pos[s] else None for s in D[n]]
 print(n,'first 30 mix indices',first[:30])
 print('same index',sum(j==i for i,j in enumerate(first,1)),'monotonic pairs',sum(a is not None and b is not None and a<b for a,b in zip(first,first[1:])))
# inspect sequence equality at offsets/segments
for off in range(0,1965):
 for n in ['endo','exo']:
  m=sum(a==b for a,b in zip(D[n],D['mix'][off:]))
  if m>20: print(n,'offset',off,'same',m)
